void ov02_02248A58(FlyResources *flyResources, NARC *narc, int memberIdx, int resourceId) {
    for (int i = 0; i < flyResources->resource1Count; i++) {
        if (flyResources->paletteSourceWrapper[i].resourceId == flyResources->resource2ID) {
            flyResources->paletteSourceWrapper[i].resourceId = resourceId;
            flyResources->paletteSourceWrapper[i].memberIdx = 0;
            flyResources->paletteSourceWrapper[i].spriteResource = (struct SpriteResource *)(AddPlttResObjFromOpenNarc(flyResources->paletteLocation, narc, memberIdx, 0, resourceId, NNS_G2D_VRAM_TYPE_2DMAIN, 1, (HeapID)(4)));
            return;
        }
    }

    ((0) ? (void)0 : GF_AssertFail());
}
